  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C75"],
      "claim": "Record C75 reports absolute oral bioavailability of 77.12% (71.83%-82.81%) in healthy volunteers under fasting conditions, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Record C38 reports absolute oral bioavailability of 23.1% (95% CI 19.2-27.8) for a 100 mg tablet in humans, at/above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Record C48 reports absolute oral bioavailability of 8.7 ± 1.6% in normal young male volunteers, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred absolute oral bioavailability records are above 20%, including 77.12% and 23.1%; one high-transferability record is low at 8.7%, so the prediction is high with moderate confidence.",
  "evidence_gaps": [
    "One high-transferability molecule reports low absolute oral bioavailability, conflicting with the majority high direction.",
    "Some records are not explicitly absolute or use unspecified bioavailability report types; dose-dependent values add uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

